(** *** Iterated phases of the 8-state proof *)

Lemma ROUNDS : forall n N T l,
  ([1;0]^^T *> 1 >> [1;0]^^(n + N) *> 1 >> l) {{G}}> const 0 -->*
  ([1;0]^^(2 * n + T) *> 1 >> [1;0]^^N *> 1 >> l) {{G}}> const 0.
Proof.
  induction n; intros.
  - finish.
  - eapply evstep_trans; [apply progress_evstep, (h8_ROUND (n + N) T l) |].
    follow (IHn N (S (S T)) l).
    finish.
Qed.

Lemma HOPS : forall M j T l,
  ([1;0]^^T *> 1 >> 0 >> 1 >> 1 >> [1;0;1]^^M *> l) <{{C}} (0 >> 1 >> 0 >> 1 >> [1;0;1]^^j *> 0 >> const 0) -->*
  ([1;0]^^T *> 1 >> 0 >> 1 >> 1 >> l) <{{C}} (0 >> 1 >> 0 >> 1 >> [1;0;1]^^(j + M) *> 0 >> const 0).
Proof.
  induction M; intros.
  - finish.
  - follow (h8_HOP M T j l).
    follow (IHM (S j) T l).
    finish.
Qed.

Lemma TLPS : forall T t J,
  ([0;1]^^T *> 1 >> 1 >> const 0) <{{C}} ([1;0;1]^^t *> 1 >> 0 >> 0 >> 1 >> 0 >> 0 >> 1 >> [0;0;1]^^J *> 0 >> 1 >> 0 >> const 0) -->*
  (1 >> 1 >> const 0) <{{C}} ([1;0;1]^^(2 * T + t) *> 1 >> 0 >> 0 >> 1 >> 0 >> 0 >> 1 >> [0;0;1]^^J *> 0 >> 1 >> 0 >> const 0).
