(** *** The token family *)

(** [lfr ds]: tokens D(d) = (10)^d 1, nearest-first, then blank. *)
Fixpoint lfr (ds : list nat) : side :=
  match ds with
  | [] => const 0
  | d :: t => [1;0]^^d *> 1 >> lfr t
  end.

(** Kr ds a r = 0^inf D(d_n) .. D(d_1) D(a) D(r+1) D(2) G> 0^inf  (r: accumulator; the BB(8) record's family
    Kc ds a b of BB8_champ35_1RB0RA.v is Kr (map (3d+1) ds) (3a+1) (3b)). *)
Definition Kr (ds : list nat) (a r : nat) : Q * tape :=
  ([1;0]^^2 *> 1 >> [1;0]^^(S r) *> 1 >> [1;0]^^a *> 1 >> lfr ds) {{G}}> const 0.

Lemma pow_add : forall (xs : list Sym) n m Y, xs^^(n + m) *> Y = xs^^n *> xs^^m *> Y.
Proof. intros. rewrite lpow_add, Str_app_assoc. reflexivity. Qed.

Lemma pow_S : forall (xs : list Sym) n Y, xs^^(S n) *> Y = xs *> xs^^n *> Y.
Proof. intros. simpl. apply Str_app_assoc. Qed.

Lemma pow_mul : forall (xs : list Sym) k n Y, xs^^(k * n) *> Y = (xs^^k)^^n *> Y.
Proof.
  induction n; intros.
  - rewrite Nat.mul_0_r. reflexivity.
  - rewrite Nat.mul_succ_r, Nat.add_comm, pow_add, IHn.
    change ((xs^^k)^^(S n)) with (xs^^k ++ (xs^^k)^^n). rewrite Str_app_assoc. reflexivity.
Qed.

Lemma lfr_rep : forall d n t, lfr (repeat d n ++ t) = ([1;0]^^d ++ [1])^^n *> lfr t.
Proof.
  induction n; intros.
  - reflexivity.
  - cbn [repeat app lfr]. rewrite pow_S, Str_app_assoc, IHn. reflexivity.
Qed.

Lemma lfr_rep_nil : forall d n, lfr (repeat d n) = ([1;0]^^d ++ [1])^^n *> const 0.
Proof. intros. rewrite <- (app_nil_r (repeat d n)), lfr_rep. reflexivity. Qed.

Lemma lfr_ones : forall n t, lfr (repeat 1%nat n ++ t) = [1;0;1]^^n *> lfr t.
Proof. intros. rewrite lfr_rep. reflexivity. Qed.

(** *** Champion rules on raw tokens (the 8-state phase lemmas are generic in the borrowed token) *)

Lemma Kr_R1 : forall ds a r, Kr ds (3 + a) r -->+ Kr ds a (2 * r + 6).
Proof.
  intros. unfold Kr.
  follow (ROUNDS (S r) O 2 ([1;0]^^(3 + a) *> 1 >> lfr ds)).
  replace (2 * S r + 2) with (S (S (S (S (2 * r))))) by lia.
  replace (S (2 * r + 6)) with (7 + 2 * r) by lia.
  apply (h8_R1F a (2 * r) (lfr ds)).
Qed.

Lemma Kr_R2 : forall x t r, Kr ((3 + x) :: t) 1 r -->+ Kr (x :: t) (2 * r + 7) 0.
Proof.
  intros. unfold Kr. cbn [lfr].
  follow (ROUNDS (S r) O 2 ([1;0]^^1 *> 1 >> [1;0]^^(3 + x) *> 1 >> lfr t)).
  replace (2 * S r + 2) with (S (S (S (S (2 * r))))) by lia.
  replace (2 * r + 7) with (7 + 2 * r) by lia.
  apply (h8_R2F (2 * r) x (lfr t)).
Qed.

Lemma Kr_R3 : forall M x t r,
  Kr (repeat 1%nat (S M) ++ (3 + x) :: t) 1 r -->+ Kr (repeat 1%nat M ++ (2 * r + 7) :: x :: t) 1 0.
Proof.
  intros. unfold Kr. rewrite !lfr_ones. cbn [lfr].
  follow (ROUNDS (S r) O 2 ([1;0]^^1 *> 1 >> [1;0;1]^^(S M) *> [1;0]^^(3 + x) *> 1 >> lfr t)).
  replace (2 * S r + 2) with (S (S (S (S (2 * r))))) by lia.
  eapply progress_evstep_trans; [apply (h8_E3 M (S (S (S (S (2 * r))))) ([1;0]^^(3 + x) *> 1 >> lfr t)) |].
  follow (HOPS M 1 (S (S (S (S (2 * r))))) ([1;0]^^(3 + x) *> 1 >> lfr t)).
  follow (h8_X3 M (S (S (S (S (2 * r))))) x (lfr t)).
  replace (2 * r + 7) with (7 + 2 * r) by lia.
  finish.
Qed.

(** *** Digit form: digits d (token 3d+1) followed by fixed raw tokens suf *)

Definition tokd (d : nat) : nat := S (3 * d).

Definition Kg (ds suf : list nat) (a b : nat) : Q * tape := Kr (map tokd ds ++ suf) (tokd a) (3 * b).

Lemma map_rep0 : forall n l, map tokd (repeat O n ++ l) = repeat 1%nat n ++ map tokd l.
Proof. induction n; intros; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

Lemma Kg_R1 : forall ds suf a b, Kg ds suf (S a) b -->+ Kg ds suf a (2 * b + 2).
Proof.
  intros. unfold Kg.
  replace (tokd (S a)) with (3 + tokd a) by (unfold tokd; lia).
  replace (3 * (2 * b + 2)) with (2 * (3 * b) + 6) by lia.
  apply Kr_R1.
Qed.

Lemma Kg_R2 : forall y t suf b, Kg (S y :: t) suf O b -->+ Kg (y :: t) suf (2 * b + 2) O.
Proof.
  intros. unfold Kg. cbn [map app].
  replace (tokd (S y)) with (3 + tokd y) by (unfold tokd; lia).
  replace (tokd (2 * b + 2)) with (2 * (3 * b) + 7) by (unfold tokd; lia).
  apply Kr_R2.
Qed.

Lemma Kg_R3 : forall M y t suf b,
  Kg (repeat O (S M) ++ S y :: t) suf O b -->+ Kg (repeat O M ++ (2 * b + 2) :: y :: t) suf O O.
Proof.
  intros. unfold Kg. rewrite !map_rep0. cbn [map]. rewrite <- !app_assoc. cbn [app].
  replace (tokd (S y)) with (3 + tokd y) by (unfold tokd; lia).
  replace (tokd (2 * b + 2)) with (2 * (3 * b) + 7) by (unfold tokd; lia).
  apply Kr_R3.
Qed.

(** The borrow from the first fixed token (3 + x), with M + 1 zero digits in between. *)
Lemma Kg_RB : forall M x suf b,
  Kg (repeat O (S M)) ((3 + x) :: suf) O b -->+ Kg (repeat O M ++ [2 * b + 2]) (x :: suf) O O.
Proof.
  intros. unfold Kg.
  rewrite <- (app_nil_r (repeat O (S M))), !map_rep0. cbn [map].
  rewrite <- !app_assoc. cbn [app].
  replace (tokd (2 * b + 2)) with (2 * (3 * b) + 7) by (unfold tokd; lia).
  apply Kr_R3.
Qed.

(** *** Exact clearing (as in BB8_champ35_bound.v) *)

Fixpoint dbl (a b : nat) : nat :=
  match a with
  | O => b
  | S a' => dbl a' (2 * b + 2)
  end.

Lemma R1ITER : forall a ds suf b, Kg ds suf a b -->* Kg ds suf O (dbl a b).
Proof.
  induction a; intros.
  - finish.
  - eapply evstep_trans; [apply progress_evstep, Kg_R1 |].
    apply IHa.
Qed.

Fixpoint iter (n : nat) (g : nat -> nat) (x : nat) : nat :=
  match n with
  | O => x
  | S n' => g (iter n' g x)
  end.

Lemma iter_S' : forall n g x, iter (S n) g x = iter n g (g x).
Proof. induction n; intros; simpl. - reflexivity. - rewrite <- IHn. reflexivity. Qed.

(** U j x: the counter after clearing one unit of a digit at depth j from counter x. *)
Fixpoint U (j : nat) : nat -> nat :=
  match j with
  | O => fun x => dbl (2 * x + 2) O
  | S i => fun x => iter (2 * x + 2) (U i) O
  end.

Lemma U_0 : forall x, U O x = dbl (2 * x + 2) O.
Proof. reflexivity. Qed.

Lemma U_S : forall j x, U (S j) x = iter (2 * x + 2) (U j) O.
Proof. reflexivity. Qed.

Opaque U.

Lemma repeat_snoc : forall (x : nat) n Us, repeat x n ++ x :: Us = repeat x (S n) ++ Us.
Proof. induction n; intros; simpl. - reflexivity. - rewrite IHn. reflexivity. Qed.

Lemma CH : forall v Us suf B, Kg (v :: Us) suf O B -->* Kg (O :: Us) suf O (iter v (U O) B).
Proof.
  induction v; intros Us suf B.
  - apply evstep_refl.
  - eapply evstep_trans; [apply progress_evstep, Kg_R2 |].
    eapply evstep_trans; [apply R1ITER |].
    rewrite iter_S', U_0.
    apply IHv.
Qed.

Lemma CDP : forall j v Us suf B,
  Kg (repeat O j ++ v :: Us) suf O B -->* Kg (repeat O (S j) ++ Us) suf O (iter v (U j) B).
Proof.
  induction j as [| n IHn].
  - intros. cbn [repeat app]. apply CH.
  - intro v. induction v as [| w IHw]; intros Us suf B.
    + rewrite repeat_snoc. apply evstep_refl.
    + eapply evstep_trans; [apply progress_evstep, Kg_R3 |].
      follow (IHn (2 * B + 2) (w :: Us) suf O).
      rewrite <- U_S.
      follow (IHw Us suf (U (S n) B)).
      rewrite iter_S'. apply evstep_refl.
Qed.

(** Clearing the first fixed token by 3 behind M + 1 zero digits: one more unit at depth M + 1. *)
Lemma CLRS : forall M x suf b,
  Kg (repeat O (S M)) ((3 + x) :: suf) O b -->* Kg (repeat O (S M)) (x :: suf) O (U (S M) b).
Proof.
  intros.
  eapply evstep_trans; [apply progress_evstep, Kg_RB |].
  follow (CDP M (2 * b + 2) [] (x :: suf) O).
  rewrite app_nil_r, <- U_S. apply evstep_refl.
Qed.

(** *** The run *)

Lemma init_reach : c0 -->* Kg (repeat O 34 ++ [2]) [] O O.
Proof.
  unfold c0, Kg, Kr.
  do 6397 step.
  apply evstep_refl'. reflexivity.
Qed.

(** The 8-state record's path into its halting configuration (R4x of BB8_champ35_bound.v). *)
Lemma R4P : forall M b, Kg (repeat O (S M)) [] O b -->* c_end M (2 * S (S (S (S (6 * b)))) + 1).
Proof.
  intros. unfold Kg, Kr. rewrite app_nil_r, <- (app_nil_r (repeat O (S M))), map_rep0, lfr_ones. cbn [lfr map].
  follow (ROUNDS (S (3 * b)) O 2 ([1;0]^^1 *> 1 >> [1;0;1]^^(S M) *> const 0)).
  replace (2 * S (3 * b) + 2) with (S (S (S (S (6 * b))))) by lia.
  eapply evstep_trans; [apply progress_evstep, (h8_E3 M (S (S (S (S (6 * b))))) (const 0)) |].
  follow (HOPS M 1 (S (S (S (S (6 * b))))) (const 0)).
  follow (h8_X4 M (S (S (S (S (6 * b)))))).
  follow (TLPS (S (S (S (S (6 * b))))) 6 M).
  replace (2 * S (S (S (S (6 * b)))) + 6) with (S (S (S (S (S (2 * S (S (S (S (6 * b)))) + 1)))))) by lia.
  exact (h8_FINx M (2 * S (S (S (S (6 * b)))) + 1)).
Qed.

(** Stage 0: the redirected halt E0 -> I rebuilds a list (generated lemma STAGE0). *)
Lemma STAGE0_Kr : forall J n,
  c_end J (S (5 * n)) -->* Kr (repeat 1%nat (J + 2 * n) ++ 7 :: 6 :: 8 :: repeat 9 n) 1 0.
Proof.
  intros. unfold c_end. rewrite pow_S, (pow_mul [1;1;0] 5 n).
  follow (STAGE0 J n).
  unfold Kr. rewrite lfr_ones, pow_add, (pow_mul [1;0;1] 2 n). cbn [lfr]. rewrite lfr_rep_nil.
  apply evstep_refl'. reflexivity.
Qed.

(** Stage 2: a zero list 5 (w + 1) long in front of D0 D8 leads to the halt (generated lemmas ST2A..ST2C). *)
Lemma STAGE2_Kr : forall w r ds, exists c,
  Kr (repeat 1%nat (5 * S w) ++ 0%nat :: 8 :: ds) 1 r -->* c /\ halted tm c.
Proof.
  intros. eexists. split.
  - unfold Kr. rewrite lfr_ones, (pow_mul [1;0;1] 5 (S w)). cbn [lfr].
    follow (ST2A r (S w) (lfr ds)).
    follow (ST2B r w (lfr ds)).
    follow (S2L_loop15 w O r (lfr ds)).
    follow (ST2C w r (lfr ds)).
    apply evstep_refl.
  - apply ST2C_halted.
Qed.

(** *** Arithmetic: the record's final counter bf and its residue mod 25 *)

Section Arith.
Local Open Scope nat_scope.

(** Knuth's up-arrows (as in BB8_champ35_bound.v): arrow 0 a b = a * b, arrow (S k) a b = (arrow k a)^b (1). *)
Fixpoint arrow (k a b : nat) : nat :=
  match k with
  | O => a * b
  | S k' => Nat.iter b (arrow k' a) 1%nat
  end.

Lemma arrow_SS : forall k a b, arrow (S k) a (S b) = arrow k a (arrow (S k) a b).
Proof. reflexivity. Qed.

Lemma arrow_S0 : forall k a, arrow (S k) a 0 = 1.
Proof. reflexivity. Qed.

Lemma arrow_S_iter : forall k a b, arrow (S k) a b = iter b (arrow k a) 1.
Proof. induction b. - reflexivity. - rewrite arrow_SS, IHb. reflexivity. Qed.

Lemma arrow_1_pow : forall a b, arrow 1 a b = a ^ b.
Proof. induction b; [reflexivity |]. rewrite arrow_SS, IHb. simpl. lia. Qed.

Lemma arrow_one : forall k, arrow k 2 1 = 2.
Proof. induction k. - reflexivity. - rewrite (arrow_SS k 2 0), arrow_S0. exact IHk. Qed.

Lemma arrow_two : forall k, arrow k 2 2 = 4.
Proof. induction k. - reflexivity. - rewrite (arrow_SS k 2 1), arrow_one. exact IHk. Qed.

Opaque arrow.

Lemma iter_add : forall a b g x, iter (a + b) g x = iter a g (iter b g x).
Proof. induction a; intros; simpl. - reflexivity. - rewrite IHa. reflexivity. Qed.

Lemma iter_ge : forall g, (forall a, a <= g a) -> forall n x, x <= iter n g x.
Proof.
  intros g Hg. induction n; intros; simpl. - lia.
  - specialize (IHn x). specialize (Hg (iter n g x)). lia.
Qed.

Lemma iter_mono_n : forall g, (forall a, a <= g a) -> forall n m x, n <= m -> iter n g x <= iter m g x.
Proof.
  intros g Hg n m x Hnm. replace m with ((m - n) + n) by lia.
  rewrite iter_add. apply iter_ge. exact Hg.
Qed.

Lemma iter_lin1 : forall g, (forall a, 1 <= a -> a + 1 <= g a) -> forall n x, 1 <= x -> x + n <= iter n g x.
Proof.
  intros g Hg. induction n; intros x Hx; simpl. - lia.
  - specialize (IHn x Hx). specialize (Hg (iter n g x) ltac:(lia)). lia.
Qed.

Lemma arrow_props : forall k,
  (forall x y, x <= y -> arrow k 2 x <= arrow k 2 y) /\ (forall x, 1 <= x -> x + 1 <= arrow k 2 x) /\
  (forall x, x <= arrow k 2 x).
Proof.
  induction k as [| k [Hm [Hs Hi]]].
  - Transparent arrow. simpl. Opaque arrow. split; [intros; lia | split; intros; lia].
  - assert (Hm' : forall x y, x <= y -> arrow (S k) 2 x <= arrow (S k) 2 y).
    { intros x y Hxy. rewrite !arrow_S_iter. apply iter_mono_n; assumption. }
    assert (Hs' : forall x, 1 <= x -> x + 1 <= arrow (S k) 2 x).
    { intros x Hx. rewrite arrow_S_iter.
      destruct x as [| x']; [lia |].
      simpl iter. pose proof (Hs (iter x' (arrow k 2) 1)).
      pose proof (iter_lin1 (arrow k 2) Hs x' 1 ltac:(lia)). lia. }
    split; [exact Hm' | split; [exact Hs' |]].
    intros x. destruct x as [| x']; [lia |]. pose proof (Hs' (S x') ltac:(lia)). lia.
Qed.

Lemma arrow_mono : forall k x y, x <= y -> arrow k 2 x <= arrow k 2 y.
Proof. intros. apply arrow_props. assumption. Qed.

Lemma arrow_gt : forall k x, 1 <= x -> x + 1 <= arrow k 2 x.
Proof. intros. apply arrow_props. assumption. Qed.

Lemma dbl_closed : forall a b, dbl a b + 2 = 2 ^ a * (b + 2).
Proof.
  induction a; intros b; simpl dbl. - simpl. lia.
  - rewrite IHa. rewrite Nat.pow_succ_r'. lia.
Qed.

(** 2 * U j x + 4 = 2 ^(j+1 arrows) (2 x + 4)  (BB8_champ35_exact.v) *)
Lemma U_closed : forall j x, 2 * U j x + 4 = arrow (S j) 2 (2 * x + 4).
Proof.
  induction j as [| j IH]; intros x.
  - rewrite (U_0 x), (arrow_1_pow 2 (2 * x + 4)).
    pose proof (dbl_closed (2 * x + 2) 0) as H.
    replace (2 * x + 4) with (S (S (2 * x + 2))) by lia.
    rewrite !Nat.pow_succ_r'. lia.
  - assert (Hit : forall n, 2 * iter n (U j) 0 + 4 = iter n (arrow (S j) 2) 4).
    { induction n as [| n IHn].
      - reflexivity.
      - simpl iter. rewrite (IH (iter n (U j) 0)), IHn. reflexivity. }
    rewrite (U_S j x), (arrow_S_iter (S j) 2 (2 * x + 4)).
    replace (2 * x + 4) with (S (S (2 * x + 2))) by lia.
    rewrite (iter_S' (S (2 * x + 2)) (arrow (S j) 2) 1).
    rewrite (iter_S' (2 * x + 2) (arrow (S j) 2) (arrow (S j) 2 1)).
    rewrite (arrow_one (S j)), (arrow_two (S j)).
    exact (Hit (2 * x + 2)).
Qed.

(** The record's counter at its first list exhaustion, sealed (lia must never see U 34 (U 34 0) unfolded). *)
Lemma bf_sig : {b : nat | b = U 34 (U 34 0)}.
Proof. exists (U 34 (U 34 0)). reflexivity. Qed.

Definition bf : nat := proj1_sig bf_sig.

Lemma bf_def : bf = U 34 (U 34 0).
Proof. exact (proj2_sig bf_sig). Qed.

Lemma arrow_37_3 : arrow 37 2 3 = arrow 35 2 (arrow 35 2 4).
Proof.
  transitivity (arrow 36 2 (arrow 37 2 2)); [exact (arrow_SS 36 2 2) |].
  rewrite (arrow_two 37).
  transitivity (arrow 35 2 (arrow 36 2 3)); [exact (arrow_SS 35 2 3) |].
  rewrite (arrow_SS 35 2 2), (arrow_two 36).
  reflexivity.
Qed.

(** 2 bf + 4 = 2 ^(37 arrows) 3 *)
Theorem bf_closed : 2 * bf + 4 = arrow 37 2 3.
Proof.
  rewrite arrow_37_3, bf_def.
  rewrite (U_closed 34 (U 34 0)).
  rewrite (U_closed 34 0).
  change (2 * 0 + 4) with 4.
  reflexivity.
Qed.

(** Every 2 ^(k arrows) n with k >= 2 is a power tower 2 ^(2 arrows) m with m >= n. *)
Lemma tower : forall k, 2 <= k -> forall n, exists m, n <= m /\ arrow k 2 n = arrow 2 2 m.
Proof.
  intros k Hk. induction k as [| k IH]; [lia |].
  destruct (Nat.eq_dec k 1) as [-> | Hk1].
  - intros n. exists n. split; reflexivity.
  - assert (Hk2 : 2 <= k) by lia. specialize (IH Hk2).
    intros n. destruct n as [| n].
    + exists 0. split; [lia |]. rewrite !arrow_S0. reflexivity.
    + rewrite arrow_SS. destruct (IH (arrow (S k) 2 n)) as [m [Hm Heq]].
      exists m. split; [| exact Heq].
      destruct n as [| n'].
      * rewrite arrow_S0 in Hm. lia.
      * pose proof (arrow_gt (S k) (S n') ltac:(lia)). lia.
Qed.

Lemma arrow2_S : forall m, arrow 2 2 (S m) = 2 ^ (arrow 2 2 m).
Proof. intros. rewrite arrow_SS, arrow_1_pow. reflexivity. Qed.

Lemma arrow2_pos : forall m, 1 <= arrow 2 2 m.
Proof. destruct m. - rewrite arrow_S0. lia. - pose proof (arrow_gt 2 (S m) ltac:(lia)). lia. Qed.

(** Residues of powers of 2 (no large numbers are ever computed). *)
Lemma pow_mod_nat : forall a b n, n <> 0 -> a ^ b mod n = (a mod n) ^ b mod n.
Proof.
  intros a b n Hn. induction b as [| b IH].
  - reflexivity.
  - simpl. rewrite (Nat.mul_mod a (a ^ b)) by exact Hn. rewrite IH.
    rewrite (Nat.mul_mod (a mod n) ((a mod n) ^ b)) by exact Hn. rewrite (Nat.mod_mod a n Hn). reflexivity.
Qed.

Lemma pow2_mod4 : forall a, 2 <= a -> 2 ^ a mod 4 = 0.
Proof.
  intros a Ha. replace a with (2 + (a - 2)) by lia. rewrite Nat.pow_add_r.
  change (2 ^ 2) with 4. rewrite Nat.mul_comm, Nat.mod_mul; lia.
Qed.

Lemma pow2_4k_mod5 : forall k, 2 ^ (4 * k) mod 5 = 1.
Proof.
  intros. rewrite Nat.pow_mul_r. change (2 ^ 4) with 16.
  rewrite pow_mod_nat by lia. change (16 mod 5) with 1. rewrite Nat.pow_1_l. reflexivity.
Qed.

Lemma pow2_20k_mod25 : forall k a, 2 ^ (20 * k + a) mod 25 = 2 ^ a mod 25.
Proof.
  intros. rewrite Nat.pow_add_r, Nat.pow_mul_r.
  rewrite Nat.mul_mod, (pow_mod_nat (2 ^ 20)) by lia.
  replace (2 ^ 20 mod 25) with 1.
  - rewrite Nat.pow_1_l. change (1 mod 25) with 1. rewrite Nat.mul_1_l. apply Nat.mod_mod. lia.
  - change 20 with (10 * 2). rewrite Nat.pow_mul_r. rewrite pow_mod_nat by lia. reflexivity.
Qed.

(** 2 ^ e1 with e1 = 2 ^ (2 ^ (2 ^ y)), y >= 1, is 36 mod 50. *)
Lemma tower_mod50 : forall y, 1 <= y -> 2 ^ (2 ^ (2 ^ (2 ^ y))) mod 50 = 36.
Proof.
  intros y Hy.
  assert (H3 : 2 <= 2 ^ y).
  { replace y with (S (y - 1)) by lia. rewrite Nat.pow_succ_r'. pose proof (Nat.pow_nonzero 2 (y - 1)). lia. }
  assert (H2a : 2 ^ (2 ^ y) mod 4 = 0) by (apply pow2_mod4; exact H3).
  assert (H2b : 2 <= 2 ^ (2 ^ y)).
  { assert (2 ^ 1 <= 2 ^ (2 ^ y)) by (apply Nat.pow_le_mono_r; lia). simpl in *. lia. }
  set (e2 := 2 ^ (2 ^ y)) in *.
  assert (Hk : exists k, e2 = 4 * k) by (exists (e2 / 4); pose proof (Nat.div_mod_eq e2 4); lia).
  destruct Hk as [k Hk].
  assert (H1a : 2 ^ e2 mod 4 = 0) by (apply pow2_mod4; lia).
  assert (H1b : 2 ^ e2 mod 5 = 1) by (rewrite Hk; apply pow2_4k_mod5).
  set (e1 := 2 ^ e2) in *.
  assert (Hj : exists j, e1 = 20 * j + 16).
  { exists (e1 / 20). pose proof (Nat.div_mod_eq e1 20). pose proof (Nat.mod_upper_bound e1 20 ltac:(lia)).
    pose proof (Nat.div_mod_eq e1 4). pose proof (Nat.div_mod_eq e1 5). lia. }
  destruct Hj as [j Hj].
  assert (H25 : 2 ^ e1 mod 25 = 11).
  { rewrite Hj, pow2_20k_mod25. change (2 ^ 16) with (256 * 256).
    rewrite Nat.mul_mod by lia. reflexivity. }
  assert (Hev : 2 ^ e1 mod 2 = 0).
  { replace e1 with (S (e1 - 1)) by lia. rewrite Nat.pow_succ_r'. rewrite Nat.mul_comm, Nat.mod_mul; lia. }
  set (x := 2 ^ e1) in *.
  pose proof (Nat.div_mod_eq x 50). pose proof (Nat.mod_upper_bound x 50 ltac:(lia)).
  pose proof (Nat.div_mod_eq x 25). pose proof (Nat.div_mod_eq x 2). lia.
Qed.

Lemma arrow37_mod50 : arrow 37 2 3 mod 50 = 36.
Proof.
  rewrite (arrow_SS 36 2 2), (arrow_two 37).
  destruct (tower 36 ltac:(lia) 4) as [m [Hm ->]].
  replace m with (S (S (S (S (m - 4))))) by lia.
  rewrite !arrow2_S. apply tower_mod50. apply arrow2_pos.
Qed.

Lemma bf_mod25 : exists s, bf = 25 * s + 16.
Proof.
  pose proof arrow37_mod50 as H. rewrite <- bf_closed in H.
  revert H. generalize bf. intros b H.
  exists (b / 25). pose proof (Nat.div_mod_eq b 25). pose proof (Nat.mod_upper_bound b 25 ltac:(lia)).
  pose proof (Nat.div_mod_eq (2 * b + 4) 50). pose proof (Nat.mod_upper_bound (2 * b + 4) 50 ltac:(lia)). lia.
Qed.

End Arith.

(** *** The chain from the blank tape *)

(** b3 s: the counter when the borrow reaches D0 (three clearings at depth K = 120 s + 115). *)
Definition Kz (s : nat) : nat := S (34 + 2 * (60 * s + 40)).
Definition B3 (s : nat) : nat := U (Kz s) (U (Kz s) (U (Kz s) O)).

Lemma Kg_digit2 : forall m suf, Kr (repeat 1%nat m ++ 7 :: suf) 1 0 = Kg (repeat O m ++ [2]) suf O O.
Proof. intros. unfold Kg. rewrite map_rep0, <- app_assoc. reflexivity. Qed.

Lemma Kg_zeros : forall m suf b, Kg (repeat O m) suf O b = Kr (repeat 1%nat m ++ suf) 1 (3 * b).
Proof. intros. unfold Kg. rewrite <- (app_nil_r (repeat O m)), map_rep0. cbn [map]. rewrite app_nil_r. reflexivity. Qed.

Lemma reach_stage2 : forall s, bf = 25 * s + 16 ->
  c0 -->* Kr (repeat 1%nat (5 * S (24 * s + 22)) ++ 0%nat :: 8 :: repeat 9 (60 * s + 40)) 1 (3 * B3 s).
Proof.
  intros s Hs.
  follow init_reach.
  follow (CDP 34 2 [] [] O).
  rewrite app_nil_r.
  assert (Hb : iter 2 (U 34) O = bf) by (rewrite bf_def; reflexivity).
  rewrite Hb.
  follow (R4P 34 bf).
  replace (2 * S (S (S (S (6 * bf)))) + 1) with (S (5 * (60 * s + 40))) by (rewrite Hs; lia).
  follow (STAGE0_Kr 34 (60 * s + 40)).
  rewrite Kg_digit2.
  follow (CDP (34 + 2 * (60 * s + 40)) 2 [] (6 :: 8 :: repeat 9 (60 * s + 40)) O).
  rewrite app_nil_r.
  assert (H1 : iter 2 (U (34 + 2 * (60 * s + 40))) O = U (Kz s) O)
    by (unfold Kz; rewrite (U_S (34 + 2 * (60 * s + 40)) O); reflexivity).
  rewrite H1.
  follow (CLRS (34 + 2 * (60 * s + 40)) 3 (8 :: repeat 9 (60 * s + 40)) (U (Kz s) O)).
  follow (CLRS (34 + 2 * (60 * s + 40)) 0 (8 :: repeat 9 (60 * s + 40)) (U (Kz s) (U (Kz s) O))).
  rewrite Kg_zeros.
  unfold B3, Kz.
  replace (S (34 + 2 * (60 * s + 40))) with (5 * S (24 * s + 22)) by lia.
  apply evstep_refl.
Qed.

Theorem halt : halts tm c0.
Proof.
  destruct bf_mod25 as [s Hs].
  destruct (STAGE2_Kr (24 * s + 22) (3 * B3 s) (repeat 9 (60 * s + 40))) as [c [H1 H2]].
  assert (Hrun : c0 -->* c) by (follow (reach_stage2 s Hs); exact H1).
  destruct (with_counter Hrun) as [n Hn].
  eapply halts_multistep; [| exact Hn].
  apply halted_halts. exact H2.
Qed.
